parameters.jsCode:
const rows = $input.all().map(r => r.json);
const today = new Date();
today.setHours(0, 0, 0, 0);

const overdueInvoices = [];

for (const row of rows) {
  if (!row.invoice_id || !row.due_date || !row.client_email) continue;

  const status = (row.status || '').toLowerCase();
  if (status === 'paid' || status === 'cancelled' || status === 'void') continue;

  const dueDate = new Date(row.due_date);
  dueDate.setHours(0, 0, 0, 0);
  if (isNaN(dueDate)) continue;

  const daysOverdue = Math.floor((today - dueDate) / 86400000);
  if (daysOverdue < 0) continue; // not due yet

  // Determine chase stage based on days overdue
  let stage = 1;
  if (daysOverdue >= 30) stage = 4;
  else if (daysOverdue >= 14) stage = 3;
  else if (daysOverdue >= 7) stage = 2;

  const lastChased = row.last_chased_at ? new Date(row.last_chased_at) : null;
  const daysSinceLastChase = lastChased
    ? Math.floor((today - lastChased) / 86400000)
    : 999;

  // Don't re-chase within 3 days unless escalating
  if (daysSinceLastChase < 3 && stage === parseInt(row.chase_stage || 1)) continue;

  overdueInvoices.push({
    invoiceId: row.invoice_id,
    clientName: row.client_name || 'Client',
    clientEmail: row.client_email,
    amount: parseFloat(row.amount) || 0,
    currency: row.currency || 'USD',
    dueDate: row.due_date,
    projectName: row.project_name || '',
    daysOverdue,
    stage,
    lastChased: row.last_chased_at || null,
    chaseCount: parseInt(row.chase_count) || 0,
    freelancerName: row.freelancer_name || $env.FREELANCER_NAME || 'Freelancer',
    notes: row.notes || ''
  });
}

return overdueInvoices.map(inv => ({ json: inv }));

