const emailBody = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
const inv = $('Find Overdue Invoices').first().json;

const stageSubjects = {
  1: `Quick reminder — Invoice ${inv.invoiceId}`,
  2: `Following up — Invoice ${inv.invoiceId} (${inv.daysOverdue} days overdue)`,
  3: `Payment required — Invoice ${inv.invoiceId}`,
  4: `Urgent: Invoice ${inv.invoiceId} — ${inv.daysOverdue} days outstanding`
};

const subject = stageSubjects[inv.stage] || `Invoice ${inv.invoiceId} follow-up`;

return [{ json: { emailBody, subject, inv } }];
